  { id: "exp-3", label: "Lunch", amount: 1350 },
];
let nextNumber = 4;

const list = document.querySelector("#expense-list");
const totalEl = document.querySelector("#total");
const formatMoney = (cents) => `$${(cents / 100).toFixed(2)}`;

function renderExpenses() {
  list.replaceChildren();
  for (const expense of expenses) {
    const li = document.createElement("li");
    li.dataset.id = expense.id;
    const label = document.createElement("span");
    label.textContent = `${expense.label}: ${formatMoney(expense.amount)}`;
    const button = document.createElement("button");
    button.type = "button";
    button.className = "delete";
    button.textContent = "Delete";
    li.append(label, button);
    list.append(li);
  }
  const total = expenses.reduce((sum, e) => sum + e.amount, 0);
  totalEl.textContent = `Total: ${formatMoney(total)}`;
}

document.querySelector("#add-sample").addEventListener("click", () => {
  expenses = [...expenses, { id: `exp-${nextNumber}`, label: `Sample ${nextNumber}`, amount: 100 }];
  nextNumber++;
  renderExpenses();
});

renderExpenses();

list.addEventListener("click", (event) => {
  const button = event.target.closest(".delete");
  if (!button) {
    return;
  }
  const id = button.closest("li").dataset.id;
  expenses = expenses.filter((e) => e.id !== id);
  renderExpenses();
});

